def list_users(limit=None, cursor=None, sort_by=None, sort_order=None, user_id=None, username=None, email=None, entity=None, created_after=None, created_before=None, q=None, include_total=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0432000" if __import__("os").path.isdir("./environment_mix/0432000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_parse(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # Validation
    if limit is not None and (not isinstance(limit, int) or limit <= 0):
        return _err("VALIDATION_ERROR", "limit must be a positive integer")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort_by is not None and sort_by not in ("created_at", "username", "user_id"):
        return _err("VALIDATION_ERROR", "Unsupported sort_by", allowed=["created_at", "username", "user_id"])
    if sort_order is not None and sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Unsupported sort_order", allowed=["asc", "desc"])
    if user_id is not None and not isinstance(user_id, str):
        return _err("VALIDATION_ERROR", "user_id must be a string")
    if username is not None and not isinstance(username, str):
        return _err("VALIDATION_ERROR", "username must be a string")
    if email is not None and not isinstance(email, str):
        return _err("VALIDATION_ERROR", "email must be a string")
    if entity is not None and not isinstance(entity, str):
        return _err("VALIDATION_ERROR", "entity must be a string")
    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string")
    if include_total is not None and not isinstance(include_total, bool):
        return _err("VALIDATION_ERROR", "include_total must be a boolean")

    dt_after = _iso_parse(created_after)
    if created_after is not None and dt_after is None:
        return _err("VALIDATION_ERROR", "created_after must be an ISO 8601 timestamp")
    dt_before = _iso_parse(created_before)
    if created_before is not None and dt_before is None:
        return _err("VALIDATION_ERROR", "created_before must be an ISO 8601 timestamp")

    users = _load("users.json")
    if isinstance(users, dict) and "data" in users and isinstance(users["data"], list):
        users = users["data"]
    if not isinstance(users, list):
        users = []

    # Filtering
    q_l = q.lower() if isinstance(q, str) and q else None
    out = []
    for u in users:
        if not isinstance(u, dict):
            continue
        if user_id is not None and u.get("user_id") != user_id:
            continue
        if username is not None and u.get("username") != username:
            continue
        if email is not None and u.get("email") != email:
            continue
        if entity is not None and u.get("entity") != entity:
            continue

        if dt_after is not None or dt_before is not None:
            u_dt = _iso_parse(u.get("created_at"))
            if u_dt is None:
                continue
            if dt_after is not None and u_dt < dt_after:
                continue
            if dt_before is not None and u_dt > dt_before:
                continue

        if q_l:
            blob = " ".join([str(u.get("user_id", "")), str(u.get("username", "")), str(u.get("email", "")), str(u.get("entity", ""))]).lower()
            if q_l not in blob:
                continue

        out.append(u)

    # Sorting
    sb = sort_by or "created_at"
    so = sort_order or "desc"

    def _sort_key(row):
        v = row.get(sb)
        if sb == "created_at":
            dt = _iso_parse(v)
            return dt if dt is not None else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return "" if v is None else str(v)

    out.sort(key=_sort_key, reverse=(so == "desc"))

    # Cursor pagination: cursor is an integer offset encoded as "offset:<n>"
    start = 0
    if cursor:
        m = re.fullmatch(r"offset:(\d+)", cursor.strip())
        if not m:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        start = int(m.group(1))
        if start < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    lim = limit if limit is not None else 100
    page = out[start:start + lim]
    next_cursor = None
    has_more = start + lim < len(out)
    if has_more:
        next_cursor = f"offset:{start + lim}"

    body = {
        "data": page,
        "meta": {
            "limit": lim,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }
    if include_total:
        body["meta"]["total"] = len(out)

    return body

