def list_runs(project_name=None, state=None, user_id=None, min_accuracy=None, max_accuracy=None, min_loss=None, max_loss=None, batch_size=None, epochs=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0432000" if __import__("os").path.isdir("./environment_mix/0432000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    # ---- validation (tool contract) ----
    if project_name is not None and not isinstance(project_name, str):
        return _err("VALIDATION_ERROR", "project_name must be a string")
    if state is not None and not isinstance(state, str):
        return _err("VALIDATION_ERROR", "state must be a string")
    if user_id is not None and not isinstance(user_id, str):
        return _err("VALIDATION_ERROR", "user_id must be a string")

    for k, v in (("min_accuracy", min_accuracy), ("max_accuracy", max_accuracy), ("min_loss", min_loss), ("max_loss", max_loss)):
        if v is not None:
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                return _err("VALIDATION_ERROR", f"{k} must be a number")

    if min_accuracy is not None and max_accuracy is not None and float(min_accuracy) > float(max_accuracy):
        return _err("VALIDATION_ERROR", "min_accuracy cannot be greater than max_accuracy")
    if min_loss is not None and max_loss is not None and float(min_loss) > float(max_loss):
        return _err("VALIDATION_ERROR", "min_loss cannot be greater than max_loss")

    if batch_size is not None and (isinstance(batch_size, bool) or not isinstance(batch_size, int)):
        return _err("VALIDATION_ERROR", "batch_size must be an integer")
    if epochs is not None and (isinstance(epochs, bool) or not isinstance(epochs, int)):
        return _err("VALIDATION_ERROR", "epochs must be an integer")

    # ---- observable dynamics: usage log + rate limit ----
    t0 = datetime.datetime.utcnow()
    usage_name = "usage.json"
    usage = _load(usage_name)
    if not isinstance(usage, list):
        usage = []

    now = datetime.datetime.utcnow()
    window_s = 60
    limit_per_window = 120
    recent = 0
    for r in usage:
        if not isinstance(r, dict):
            continue
        ts = r.get("timestamp")
        dt = _parse_iso(ts) if ts is not None else None
        if dt is None:
            continue
        if (now - dt).total_seconds() <= window_s:
            recent += 1
    if recent >= limit_per_window:
        # log the refused call
        usage.append({
            "timestamp": _utcnow_iso(),
            "endpoint": "list_runs",
            "status": "RATE_LIMIT",
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
        })
        _save(usage_name, usage)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- read runs from real datastore (map to traces collection) ----
    traces = _load("traces.json")
    if isinstance(traces, dict) and "rows" in traces and isinstance(traces.get("rows"), list):
        traces = traces["rows"]
    if not isinstance(traces, list):
        traces = []

    users = _load("users.json")
    if isinstance(users, dict) and "rows" in users and isinstance(users.get("rows"), list):
        users = users["rows"]
    if not isinstance(users, list):
        users = []

    projects = _load("projects.json")
    if isinstance(projects, dict) and "rows" in projects and isinstance(projects.get("rows"), list):
        projects = projects["rows"]
    if not isinstance(projects, list):
        projects = []

    # validate project_name existence if provided (realistic referential check)
    if project_name is not None:
        if not any(isinstance(p, dict) and p.get("name") == project_name for p in projects):
            usage.append({
                "timestamp": _utcnow_iso(),
                "endpoint": "list_runs",
                "status": "NOT_FOUND",
                "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            })
            _save(usage_name, usage)
            return _err("NOT_FOUND", "project_name not found")

    # validate user_id existence if provided (referential check)
    if user_id is not None:
        if not any(isinstance(u, dict) and u.get("user_id") == user_id for u in users):
            usage.append({
                "timestamp": _utcnow_iso(),
                "endpoint": "list_runs",
                "status": "NOT_FOUND",
                "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
            })
            _save(usage_name, usage)
            return _err("NOT_FOUND", "user_id not found")

    # The datastore doesn't have a separate runs collection; treat traces as runs.
    # Map filters best-effort:
    # - project_name -> trace.project_name
    # - state -> trace.status (success/error) OR allow common synonyms
    # - user_id / accuracy/loss/batch_size/epochs are not present in schema; ignore safely (no failure).
    state_map = {
        "finished": "success",
        "succeeded": "success",
        "success": "success",
        "failed": "error",
        "error": "error",
        "errored": "error",
    }
    wanted_status = None
    if state is not None:
        key = state.strip().lower()
        wanted_status = state_map.get(key, state)  # if caller already uses "success"/"error", keep it

    out = []
    for tr in traces:
        if not isinstance(tr, dict):
            continue
        if project_name is not None and tr.get("project_name") != project_name:
            continue
        if wanted_status is not None:
            # if trace has no status, it can't match
            if tr.get("status") != wanted_status:
                continue
        # user_id/accuracy/loss/batch_size/epochs cannot be applied (fields absent); do not exclude rows.
        out.append(tr)

    # success log
    usage.append({
        "timestamp": _utcnow_iso(),
        "endpoint": "list_runs",
        "status": "OK",
        "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000),
        "result_count": len(out),
    })
    _save(usage_name, usage)

    return {
        "runs": out,
        "count": len(out),
    }

