def list_traces(project_name=None, status=None, parent_id=None, op_name_contains=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0432000" if __import__("os").path.isdir("./environment_mix/0432000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    ALLOWED_PROJECTS = {"data-preprocessing", "gan-experiments", "image-classification", "nlp-sentiment", "reinforcement-learning"}
    ALLOWED_STATUS = {"success", "error"}

    if project_name is not None:
        if not isinstance(project_name, str):
            return _err("VALIDATION_ERROR", "project_name must be a string")
        if project_name not in ALLOWED_PROJECTS:
            return _err("VALIDATION_ERROR", "Unsupported project_name", allowed=sorted(ALLOWED_PROJECTS))
        projects = _load("projects.json")
        if isinstance(projects, dict) and "data" in projects and isinstance(projects["data"], list):
            projects = projects["data"]
        if not isinstance(projects, list):
            projects = []
        if not any(isinstance(p, dict) and p.get("name") == project_name for p in projects):
            return _err("NOT_FOUND", "Project not found", project_name=project_name)

    if status is not None:
        if not isinstance(status, str) or status not in ALLOWED_STATUS:
            return _err("VALIDATION_ERROR", "Unsupported status", allowed=sorted(ALLOWED_STATUS))
    if parent_id is not None:
        if not isinstance(parent_id, str) or not parent_id.strip():
            return _err("VALIDATION_ERROR", "parent_id must be a non-empty string")
    if op_name_contains is not None and not isinstance(op_name_contains, str):
        return _err("VALIDATION_ERROR", "op_name_contains must be a string")

    traces = _load("traces.json")
    if isinstance(traces, dict) and "data" in traces and isinstance(traces["data"], list):
        traces = traces["data"]
    if not isinstance(traces, list):
        traces = []

    out = []
    substr = op_name_contains if isinstance(op_name_contains, str) and op_name_contains else None
    for tr in traces:
        if not isinstance(tr, dict):
            continue
        if project_name is not None and tr.get("project_name") != project_name:
            continue
        if status is not None and tr.get("status") != status:
            continue
        if parent_id is not None and tr.get("parent_id") != parent_id:
            continue
        if substr is not None:
            opn = tr.get("op_name") or ""
            if not isinstance(opn, str) or substr not in opn:
                continue
        out.append(tr)

    return {"data": out, "meta": {"total": len(out)}}

def get_trace(trace_id, **_extra):
    import json, os, datetime, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0432000" if __import__("os").path.isdir("./environment_mix/0432000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if trace_id is None or not isinstance(trace_id, str) or not trace_id.strip():
        return _err("VALIDATION_ERROR", "trace_id is required and must be a non-empty string")
    try:
        uuid.UUID(trace_id)
    except Exception:
        return _err("VALIDATION_ERROR", "trace_id must be a valid UUID")

    traces = _load("traces.json")
    if isinstance(traces, dict) and "data" in traces and isinstance(traces["data"], list):
        traces = traces["data"]
    if not isinstance(traces, list):
        traces = []

    # traces are span-like rows; multiple rows can share a trace_id; return the first matching row as "the trace record"
    for tr in traces:
        if isinstance(tr, dict) and tr.get("trace_id") == trace_id:
            return {"data": tr}

    return _err("NOT_FOUND", "Trace not found", trace_id=trace_id)
